#### 347. 前 K 个高频元素
(https://leetcode.cn/problems/top-k-frequent-elements/)
```cpp
// 优先队列 nlogn k // 2026-03-19 15:05:54
class Solution {
  public:
	vector<int> topKFrequent(vector<int>& nums, int k) {
		auto cmp = [](const pair<int, int> p1, pair<int, int>& p2) -> bool { return p1.second > p2.second; };
		unordered_map<int, int>												  m;
        ranges::for_each(nums, [&m](const int x) { m[x]++; });
// 
        priority_queue<pair<int, int>, vector<pair<int, int>>, decltype(cmp)> pq(cmp);
		ranges::for_each(m, [&pq, k](const pair<int, int>& p) {
			pq.push({ p.first, p.second });
			if(pq.size() > k) {
				pq.pop();
			}
		});
		vector<int> result;
		result.reserve(k);
		generate_n(back_inserter(result), pq.size(), [&pq]() {
			int temp = pq.top().first;
			pq.pop();
			return temp;
		});
		return result;
	}
};
```
- 不使用显式循环，lambda 表达式中的嵌套和捕获列表用多了可读性暴跌
